const a={"pull-up":{squeeze_cue:"Lleva los codos hacia abajo, a los bolsillos traseros, y aprieta fuerte los dorsales cuando la barbilla pase la barra.",posture_tips:["Cuélgate de la barra con agarre prono un poco más ancho que los hombros, brazos totalmente estirados y piernas juntas.","Activa el core y aprieta los glúteos para que tu cuerpo quede en una sola línea, sin balancearte.","Primero baja las escápulas, sube hasta que la barbilla pase la barra y baja en 2-3 segundos hasta quedar completamente colgado.","No hagas kipping con las piernas ni recortes las repeticiones dejando los codos doblados abajo.","Al terminar la serie, bájate hasta quedar completamente colgado en lugar de soltarte desde arriba."]},"pull-up-wide-grip":{squeeze_cue:"Lleva los codos hacia abajo y afuera, hacia las caderas, y aprieta los bordes externos de los dorsales como si cerraras unas alas.",posture_tips:["Agarra la barra en prono a unas 1.5 veces el ancho de hombros y cuélgate con los brazos rectos y los hombros activos.","Lleva el pecho hacia la barra y mantén los codos apuntando hacia afuera y abajo, no hacia adelante.","Sube hasta que la parte alta del pecho se acerque a la barra, haz una pausa breve y baja en 2-3 segundos hasta estirar los brazos.","No abras tanto el agarre que pierdas rango de movimiento o que los hombros suban hacia las orejas.","Cierra el agarre si la posición ancha te causa molestia en los hombros en la parte baja."]},"neutral-grip-weighted-chin-ups":{squeeze_cue:"Lleva los codos directo hacia abajo, a las costillas, y aprieta los dorsales como si exprimieras una naranja en cada axila.",posture_tips:["Cuélgate de las asas paralelas con las palmas enfrentadas y los brazos totalmente extendidos.","Mantén las costillas abajo e inclina el torso ligeramente hacia atrás mientras subes.","Jala con los codos pegados a los costados hasta que la barbilla pase las asas y luego baja en 2-3 segundos.","No encojas los hombros al inicio; baja las escápulas antes de doblar los codos.","Si agregas peso, asegura el cinturón o la mancuerna para que no se balancee entre tus piernas."]},"reverse-grip-chin-up-weighted":{squeeze_cue:"Lleva los codos hacia las caderas y aprieta dorsales y bíceps a la vez mientras el pecho sube hacia la barra.",posture_tips:["Agarra la barra al ancho de hombros con las palmas hacia ti y cuélgate con los brazos rectos.","Mantén el torso estable y los codos frente a tu cuerpo, apuntando al piso.","Sube hasta que la barbilla pase la barra y luego baja en 2-3 segundos hasta quedar completamente colgado.","No te detengas a medio camino al bajar; la extensión completa trabaja los dorsales en su posición estirada.","Agrega carga en saltos pequeños solo cuando completes todas las repeticiones desde colgado completo."]},"machine-assisted-pull-up":{squeeze_cue:"Lleva los codos hacia abajo, a los costados, y aprieta los dorsales abajo, sosteniendo la contracción un instante.",posture_tips:["Ajusta el contrapeso, apoya las rodillas o los pies en la plataforma y agarra las asas superiores.","Mantén el torso erguido y el pecho arriba sin recargarte en la plataforma.","Sube hasta que la barbilla pase las asas, haz una pausa de un segundo y baja en 3 segundos hasta estirar los brazos.","No uses tanta asistencia que la plataforma te impulse; redúcela a medida que te hagas más fuerte.","Mantén ambas manos en las asas al subir y bajar de la plataforma para que no dé un tirón."]},"band-assisted-pull-up":{squeeze_cue:"Lleva los codos a los bolsillos traseros y aprieta fuerte los dorsales arriba en lugar de dejar que la banda te suba.",posture_tips:["Pasa la banda por la barra y mete una rodilla o un pie en ella antes de colgarte con agarre prono.","Mantén el cuerpo en línea recta y el core firme para que la banda no te balancee.","Sube hasta que la barbilla pase la barra y baja en 2-3 segundos para que la banda no te jale de golpe hacia arriba.","No dependas siempre de una banda gruesa; cambia a una más ligera cuando logres tus repeticiones objetivo.","Revisa que la banda no tenga cortes y que esté bien sujeta antes de cada serie."]},"lat-pulldown":{squeeze_cue:"Lleva los codos hacia abajo, a los bolsillos traseros, y aprieta fuerte los dorsales abajo.",posture_tips:["Ajusta la almohadilla bien firme sobre los muslos y agarra la barra en prono, más ancho que los hombros.","Inclínate unos grados hacia atrás con el pecho arriba y la zona lumbar neutra.","Jala la barra a la parte alta del pecho, pausa un segundo y déjala subir en 2-3 segundos hasta estirar los dorsales.","No bajes la barra detrás de la nuca ni balancees el torso hacia atrás para mover más peso.","Regresa la barra arriba antes de pararte para que las placas no golpeen."]},"neutral-grip-lat-pulldown":{squeeze_cue:"Lleva los codos hacia abajo pegados a las costillas y aprieta los dorsales como si sujetaras un periódico bajo cada brazo.",posture_tips:["Coloca un asa de agarre neutro y siéntate con los muslos bajo la almohadilla y los brazos totalmente extendidos.","Mantén el pecho arriba y los codos cerca del cuerpo, apuntando al piso.","Jala el asa hasta el esternón, haz una pausa breve y regresa en 2-3 segundos hasta la extensión completa.","No redondees la espalda al final del jalón para acercar el asa al pecho.","Asegúrate de que el mosquetón del asa esté bien cerrado antes de cargar el peso."]},"single-arm-lat-pulldown":{squeeze_cue:"Lleva el codo hacia abajo, al bolsillo de la cadera, y aprieta el dorsal de ese lado, sintiendo cómo se acorta junto a las costillas.",posture_tips:["Siéntate bajo la polea alta con un asa individual y el brazo de trabajo totalmente estirado sobre la cabeza.","Mantén el torso de frente y estable, sin girar hacia el lado que trabaja.","Lleva el codo hacia la cadera en una ligera diagonal y luego deja que el brazo suba en 2-3 segundos.","No compenses inclinándote de lado; el movimiento debe salir del hombro y el codo.","Empieza con el brazo más débil e iguala las repeticiones con el otro lado."]},"cable-lat-pulldown-underhand-grip":{squeeze_cue:"Lleva los codos hacia abajo junto a las costillas y aprieta fuerte la parte baja de los dorsales cuando la barra toque el pecho.",posture_tips:["Agarra una barra recta al ancho de hombros con las palmas hacia ti y fija los muslos bajo la almohadilla.","Mantén el pecho arriba con una ligera inclinación hacia atrás, sin arquear de más la zona lumbar.","Jala la barra a la parte baja del pecho con los codos pegados, pausa y regresa en 2-3 segundos hasta estirar por completo.","No lo conviertas en un curl de bíceps: piensa en llevar los codos hacia abajo, no en doblar las muñecas.","Usa un peso que puedas controlar en la subida sin que te levante del asiento."]},"reverse-grip-lats-machine":{squeeze_cue:"Lleva los codos hacia las caderas y aprieta los dorsales abajo como si los guardaras en los bolsillos traseros.",posture_tips:["Ajusta el asiento para alcanzar las asas con los brazos extendidos y las palmas hacia ti.","Apóyate firme contra la almohadilla del pecho o de los muslos y mantén la espalda neutra.","Jala las asas hacia abajo siguiendo el arco de la máquina, pausa un segundo y regresa en 2-3 segundos hasta estirar por completo.","No te despegues del asiento ni de la almohadilla para ganar rango con impulso.","Revisa que el pasador del peso esté bien insertado antes de empezar."]},"plate-loaded-lat-pulldown":{squeeze_cue:"Lleva los codos hacia abajo y atrás, a los costados, y aprieta fuerte los dorsales al final de cada jalón.",posture_tips:["Carga los discos por igual en ambos lados, fija los muslos bajo la almohadilla y agarra las asas.","Mantén el pecho arriba y el torso quieto durante todo el movimiento.","Jala las asas hacia los costados del pecho, pausa y déjalas subir en 2-3 segundos hasta estirar los brazos.","No dejes que las asas suban de golpe; controla la fase excéntrica en cada repetición.","Pon y quita discos con la máquina en reposo, alternando lados para que no se desequilibre."]},"barbell-bent-over-row":{squeeze_cue:"Lleva los codos hacia atrás y junta las escápulas como si sostuvieras un lápiz entre ellas.",posture_tips:["Agarra la barra en prono un poco más ancho que los hombros, rodillas sueltas, e inclina el torso a unos 45 grados.","Mantén la espalda neutra y el cuello alineado, con la mirada en el piso un poco delante de ti.","Rema la barra hacia el ombligo, pausa un segundo y baja en 2 segundos hasta estirar los brazos sin mover el torso.","No te enderezes en cada repetición para subir la barra con impulso.","Baja la carga en cuanto ya no puedas mantener la espalda neutra."]},"bb-bent-over-reverse-grip-rows":{squeeze_cue:"Lleva los codos hacia atrás, más allá de las caderas, y aprieta fuerte los dorsales como si sujetaras un libro bajo cada brazo.",posture_tips:["Agarra la barra al ancho de hombros con las palmas hacia adelante e inclínate desde la cadera con las rodillas sueltas.","Mantén el torso inclinado y firme, el core activo y la barra cerca de los muslos.","Rema la barra hacia la parte baja del abdomen con los codos cerca, pausa y baja en 2 segundos hasta estirar los brazos.","No flexiones las muñecas ni conviertas el remo en un curl de bíceps.","Levanta la barra del piso con la espalda neutra y usando las piernas, nunca con la espalda redondeada."]},"barbell-pendlay-row":{squeeze_cue:"Jala la barra con fuerza hacia el abdomen y junta las escápulas con fuerza por una fracción de segundo arriba.",posture_tips:["Colócate con la barra en el piso sobre la mitad del pie y el torso casi paralelo al suelo.","Mantén la espalda plana y la cadera alta, con el mismo ángulo de torso en cada repetición.","Rema la barra de forma explosiva hacia el abdomen, bájala al piso con control y haz una pausa completa en cada repetición.","No levantes el torso para ayudar a subir la barra; si lo necesitas, la carga es demasiado pesada.","Baja la barra con control en lugar de soltarla, manteniendo la espalda plana al apoyarla."]},"smith-machine-bent-over-row":{squeeze_cue:"Lleva los codos hacia el techo y junta las escápulas cuando la barra toque el abdomen.",posture_tips:["Coloca los topes de seguridad a la altura de las rodillas, agarra la barra en prono e inclina el torso desde la cadera.","Colócate de modo que la barra suba recta hacia el abdomen sin chocar con los muslos.","Rema la barra hacia el ombligo, pausa un segundo y baja en 2 segundos hasta estirar los brazos.","No te pongas ni muy cerca ni muy lejos de la barra; el recorrido fijo exige una posición precisa.","Gira la barra para engancharla en los ganchos antes de soltarla al final."]},"barbell-seal-row":{squeeze_cue:"Sube los codos más allá del torso y junta las escápulas cuando la barra toque el banco.",posture_tips:["Acuéstate boca abajo en un banco plano alto con la barra debajo y los brazos colgando rectos.","Mantén el pecho y la cadera sobre el banco y la cabeza alineada con el torso.","Rema la barra hasta que toque la parte inferior del banco, pausa y baja en 2-3 segundos hasta la extensión completa.","No despegues el pecho del banco para ganar rango; pierdes apoyo y tensión.","Asegúrate de que el banco esté estable sobre cajones o soportes antes de acostarte."]},"barbell-t-bar-row":{squeeze_cue:"Lleva los codos hacia atrás y aprieta la parte media de la espalda como si rompieras una nuez entre las escápulas.",posture_tips:["Párate con la barra anclada entre las piernas y un agarre en V bajo los discos, rodillas flexionadas y cadera inclinada.","Mantén el torso a unos 45 grados y la espalda neutra durante todo el jalón.","Rema el agarre hacia la parte baja del pecho, pausa un segundo y baja en 2 segundos hasta estirar los brazos.","No cargues discos grandes que acorten tu rango o te obliguen a balancearte.","Asegura el extremo de la barra en un landmine o en una esquina para que no se deslice."]},"plate-loaded-t-bar-row-chest-supported":{squeeze_cue:"Lleva los codos detrás del cuerpo y junta fuerte las escápulas mientras el pecho sigue pegado a la almohadilla.",posture_tips:["Súbete a la plataforma, apoya el pecho en la almohadilla y agarra las asas con los brazos rectos.","Mantén el pecho en la almohadilla y el cuello neutro, sin levantar la cabeza.","Rema las asas hacia el torso, pausa un segundo y baja en 2-3 segundos hasta estirar los brazos.","No despegues el pecho de la almohadilla para empujar con las piernas al final del jalón.","Sube y baja de la plataforma solo con la carga en su posición de reposo."]},"barbell-meadows-row":{squeeze_cue:"Lleva el codo hacia arriba y atrás, hacia la cadera, y aprieta arriba el dorsal y la parte alta de la espalda de ese lado.",posture_tips:["Párate perpendicular a la barra anclada, agarra el extremo en prono y apoya el antebrazo libre en la rodilla.","Mantén la cadera alta, el torso inclinado y la espalda neutra, sin rotar.","Rema el extremo de la barra hacia la cadera con el codo abierto, pausa y baja en 2 segundos hasta estirar el dorsal.","No abras el torso girándolo para mover la carga; mantén la rotación al mínimo.","Usa discos más pequeños para tener más rango y ancla bien la barra antes de empezar."]},"dumbbell-row-single-arm":{squeeze_cue:"Lleva el codo hacia la cadera como si arrancaras una podadora y aprieta fuerte el dorsal arriba.",posture_tips:["Apoya una rodilla y una mano en el banco, con la mancuerna colgando bajo el hombro del brazo libre.","Mantén la espalda plana y paralela al piso, con los hombros nivelados.","Jala la mancuerna hacia la cadera rozando el costado, pausa y baja en 2 segundos hasta estirar el dorsal.","No gires el torso hacia arriba en cada repetición para levantar más peso.","Levanta y deja la mancuerna con la espalda neutra mientras te apoyas en el banco."]},"dumbbell-bent-over-row":{squeeze_cue:"Lleva ambos codos hacia atrás y junta las escápulas como si apretaras una moneda entre ellas.",posture_tips:["Sostén una mancuerna en cada mano, flexiona un poco las rodillas e inclina el torso desde la cadera.","Mantén la espalda neutra y el peso repartido en todo el pie.","Rema ambas mancuernas hacia la cintura con los codos cerca, pausa y baja en 2 segundos.","No dejes caer la cabeza ni redondees los hombros hacia adelante al bajar.","Cambia a la versión con apoyo de pecho si tu zona lumbar se cansa antes que la parte alta de la espalda."]},"dumbbell-chest-supported-row":{squeeze_cue:"Lleva los codos hacia el techo y junta las escápulas como si sostuvieras un lápiz entre ellas.",posture_tips:["Acuéstate boca abajo en un banco inclinado a unos 30-45 grados con una mancuerna en cada mano.","Mantén el pecho en la almohadilla y las puntas de los pies firmes en el piso para no resbalar.","Lleva los codos hacia atrás hasta juntar las escápulas, sostén 1 segundo y baja en 2-3 segundos.","No estires el cuello para mirar al frente; mantén la mirada hacia el piso.","Deja las mancuernas en el piso antes de levantarte del banco."]},"kettlebell-row-single-arm":{squeeze_cue:"Lleva el codo hacia atrás, al bolsillo de la cadera, y aprieta fuerte el dorsal mientras la kettlebell sigue pegada a tu costado.",posture_tips:["Párate con los pies escalonados, apoya la mano libre en un banco o en el muslo y agarra el asa de la kettlebell.","Mantén el torso inclinado y estable, con la cadera paralela al piso.","Rema la kettlebell hacia la cadera con la muñeca recta, pausa y baja en 2 segundos.","No dejes que la kettlebell se balancee entre repeticiones; detenla abajo en cada una.","Sujeta el asa con firmeza y asegúrate de tener espacio libre a tu alrededor al remar."]},"seated-cable-row":{squeeze_cue:"Lleva los codos hacia atrás, más allá de las costillas, y junta las escápulas como si sostuvieras un lápiz entre ellas.",posture_tips:["Siéntate con los pies en la plataforma y las rodillas un poco flexionadas, sosteniendo el agarre en V con los brazos extendidos.","Mantén el torso erguido y quieto, el pecho arriba y los hombros lejos de las orejas.","Rema el agarre hacia el abdomen, sostén 1 segundo y extiende en 2-3 segundos dejando que los hombros se estiren hacia adelante.","No balancees el torso hacia adelante y atrás para mover el peso con la zona lumbar.","Toma y suelta el agarre con las rodillas flexionadas para no dar un tirón a tu zona lumbar."]},"wide-grip-cable-row":{squeeze_cue:"Lleva los codos abiertos y hacia atrás y aprieta la espalda media y los deltoides posteriores como si doblaras la barra en forma de U.",posture_tips:["Coloca una barra larga, agárrala en prono más ancho que los hombros y siéntate con la espalda erguida.","Mantén los codos abiertos a unos 60-70 grados del torso y el pecho arriba.","Rema la barra hacia la parte baja del pecho, sostén 1 segundo y regresa en 2-3 segundos.","No encojas los hombros al final del jalón; termina con las escápulas, no con el cuello.","Elige un peso que puedas controlar en el regreso sin que te jale hacia adelante."]},"cable-seated-row-underhand-grip":{squeeze_cue:"Lleva los codos hacia atrás, más allá de las caderas, y aprieta fuerte los dorsales, sintiendo cómo se tensan a lo largo de las costillas bajas.",posture_tips:["Agarra una barra recta al ancho de hombros con las palmas hacia arriba y siéntate erguido con las rodillas un poco flexionadas.","Mantén los codos pegados al cuerpo y el torso firme durante el jalón.","Rema la barra hacia el ombligo, pausa un segundo y regresa en 2-3 segundos hasta estirar los brazos.","No levantes ni abras los codos; perderías el énfasis en los dorsales.","Mantén las muñecas rectas y alineadas con los antebrazos durante toda la serie."]},"single-hand-cable-unilateral-rows":{squeeze_cue:"Lleva el codo hacia atrás, al bolsillo de la cadera, y aprieta el dorsal de ese lado cuando el asa llegue a tu cintura.",posture_tips:["Siéntate frente a la polea con un asa individual y el brazo extendido hacia adelante.","Mantén los hombros nivelados y el torso estable, permitiendo solo una ligera rotación.","Rema el asa hacia la cadera, pausa y extiende en 2-3 segundos dejando que el hombro se estire hacia adelante.","No gires todo el torso para terminar la repetición; el trabajo debe venir de tu espalda.","Empieza con el lado más débil y apoya la mano libre en el muslo para tener estabilidad."]},"wide-grip-cable-chest-pulls":{squeeze_cue:"Lleva los codos abiertos y hacia atrás y aprieta los deltoides posteriores y la espalda media cuando la barra llegue al pecho.",posture_tips:["Párate frente a la polea con una barra larga a la altura del pecho y toma un agarre prono ancho.","Mantén el torso erguido y el pecho arriba, con los codos a la altura de los hombros o un poco más abajo.","Jala la barra al pecho abriendo los codos, sostén 1 segundo y regresa en 2-3 segundos hasta estirar los brazos.","No te inclines hacia atrás para acercar la barra; tu torso no debe moverse.","Ajusta la altura de la polea y el peso antes de empezar para jalar sin tensión en el cuello."]},"wide-grip-supp-seated-row":{squeeze_cue:"Lleva los codos abiertos y detrás de ti y aprieta la parte alta de la espalda como si apretaras una pelota de tenis entre las escápulas.",posture_tips:["Ajusta el asiento y la almohadilla para que las asas anchas queden a la altura del pecho con los brazos extendidos.","Mantén el pecho en la almohadilla y los codos abiertos hacia los lados.","Rema hacia atrás hasta que los codos pasen el torso, sostén 1 segundo y regresa en 2-3 segundos.","No despegues el pecho de la almohadilla al final de cada repetición para ganar rango.","Revisa que el pasador esté bien insertado y el asiento asegurado antes de cada serie."]},"neutral-grip-supp-rows":{squeeze_cue:"Lleva los codos hacia atrás a lo largo de los costados y junta las escápulas como si sostuvieras un lápiz entre ellas.",posture_tips:["Siéntate con el pecho contra la almohadilla y toma las asas verticales con las palmas enfrentadas.","Mantén la espalda neutra y los codos cerca del cuerpo durante todo el remo.","Jala hasta que los codos queden detrás del torso, pausa y estira los brazos en 2-3 segundos.","No encojas los hombros ni adelantes la cabeza al final del jalón.","Deja que el peso regrese a reposo con control al terminar la serie."]},"unilateral-supp-rows-reverse-grip":{squeeze_cue:"Lleva el codo hacia atrás, más allá de la cadera, y aprieta el dorsal de ese lado como si lo guardaras en el bolsillo trasero.",posture_tips:["Apoya el pecho en la almohadilla y toma un asa con la palma hacia arriba y el brazo extendido.","Mantén el pecho fijo y los hombros paralelos a la almohadilla, sin girar el torso.","Lleva el codo hacia atrás pegado al costado, hacia la cadera, pausa y regresa en 2-3 segundos hasta estirar por completo.","No empujes la máquina con la mano libre para ayudarte a jalar.","Entrena ambos lados con la misma carga y repeticiones para mantener el equilibrio."]},"plate-loaded-low-row":{squeeze_cue:"Lleva los codos hacia atrás, hacia las caderas, y aprieta los dorsales y la espalda media al final del jalón.",posture_tips:["Ajusta el asiento para que el pecho quede contra la almohadilla y toma las asas bajas con los brazos extendidos.","Mantén el pecho en la almohadilla y el torso erguido, sin inclinarte hacia atrás.","Rema las asas hacia la cadera, pausa un segundo y regresa en 2-3 segundos hasta estirar la espalda.","No acortes el rango; deja que las escápulas se separen en cada estiramiento.","Carga los discos por igual y quítalos al terminar para dejar la máquina segura."]},"plate-loaded-high-row":{squeeze_cue:"Lleva los codos hacia abajo y atrás, detrás de ti, y aprieta los dorsales mientras juntas las escápulas abajo.",posture_tips:["Fija los muslos bajo la almohadilla y toma las asas altas con los brazos extendidos sobre la cabeza.","Mantén el pecho arriba con una ligera inclinación hacia adelante, sin arquear la zona lumbar.","Jala las asas hacia abajo y atrás hasta el pecho, pausa y regresa en 2-3 segundos hasta arriba.","No dejes que el peso te levante del asiento al subir.","Ajusta la almohadilla de los muslos para quedar bien fijo antes de cargar discos pesados."]},"inverted-row":{squeeze_cue:"Lleva el pecho a la barra y junta las escápulas como si intentaras romper una nuez entre ellas.",posture_tips:["Colócate bajo una barra fija a la altura de la cadera, agárrala en prono y extiende el cuerpo con los talones en el piso.","Mantén el cuerpo rígido como en una plancha, con glúteos y abdomen apretados.","Jala hasta que el pecho toque la barra, sostén 1 segundo y baja en 2 segundos hasta estirar los brazos.","No dejes que la cadera se hunda ni que suba antes que el pecho durante el jalón.","Asegúrate de que la barra del rack o de la máquina Smith esté bien trabada antes de colgarte."]},"db-pull-overs":{squeeze_cue:"Regresa la mancuerna sobre el pecho llevando los brazos hacia las caderas y apretando los dorsales.",posture_tips:["Acuéstate en el banco sosteniendo una mancuerna con ambas manos sobre el pecho, codos ligeramente flexionados.","Mantén las costillas abajo y la zona lumbar estable, sin arquearte mientras baja el peso.","Lleva la mancuerna en arco detrás de la cabeza en 2-3 segundos hasta sentir el estiramiento y luego regrésala sobre el pecho.","No flexiones y extiendas los codos en cada repetición; mantén fijo el ángulo del codo.","Sujeta la mancuerna por debajo del disco superior con las manos entrelazadas para que no se resbale."]},"ez-bar-pullover":{squeeze_cue:"Regresa la barra sobre el pecho llevando los codos hacia las caderas y aprieta los dorsales como si cerraras un libro.",posture_tips:["Acuéstate en un banco plano con la barra EZ sobre el pecho, usando un agarre prono cerrado.","Mantén la cabeza apoyada, los pies firmes y los codos ligeramente flexionados durante todo el arco.","Baja la barra detrás de la cabeza en 2-3 segundos hasta estirar los dorsales y luego regrésala sobre el pecho.","No pases del punto que puedas controlar ni arquees la espalda para buscar más rango.","Usa una carga moderada; la barra pasa sobre tu cara y debes poder detenerla en cualquier momento."]},"machine-pullover":{squeeze_cue:"Lleva la parte posterior de los brazos hacia los costados y aprieta fuerte los dorsales como si sujetaras una toalla bajo cada brazo.",posture_tips:["Ajusta el asiento para que tus hombros queden alineados con el eje de la máquina y apoya los codos en las almohadillas.","Mantén la espalda contra el respaldo y abróchate el cinturón si la máquina lo tiene.","Lleva los codos hacia abajo en arco hasta los costados, sostén 1 segundo y regresa en 2-3 segundos hasta estirar los dorsales.","No jales con las manos; empuja con la parte posterior de los brazos.","Baja la carga y revisa la alineación con el eje si sientes el trabajo en la parte frontal de los hombros."]},"cable-straight-arms-pull-downs":{squeeze_cue:"Lleva las manos en arco hasta los muslos y aprieta fuerte los dorsales, sintiendo cómo envuelven tus costillas abajo.",posture_tips:["Párate frente a la polea alta con una barra recta o cuerda, brazos extendidos y torso ligeramente inclinado hacia adelante.","Mantén los codos casi bloqueados y la espalda neutra, con la cadera un poco hacia atrás.","Baja la barra en arco hasta los muslos, sostén 1 segundo y déjala subir en 2-3 segundos hasta la altura de los ojos.","No dobles los codos ni lo conviertas en una extensión de tríceps en polea.","Da un paso atrás después de tomar la barra para que la carga no te jale hacia adelante al inicio."]},"band-straight-arm-pulldown":{squeeze_cue:"Empuja las manos hacia las caderas y aprieta fuerte los dorsales abajo como si presionaras la banda contra tus muslos.",posture_tips:["Ancla la banda por encima de la cabeza, tómala con ambas manos y da pasos atrás hasta que tenga tensión.","Mantén los brazos rectos, el pecho arriba y una ligera bisagra de cadera.","Lleva las manos en arco hasta las caderas, sostén 1 segundo y regresa en 2-3 segundos a la altura de los hombros.","No encojas los hombros mientras la banda jala tus brazos hacia arriba.","Revisa el anclaje y el estado de la banda; si se zafa, puede regresar de golpe hacia ti."]},"barbell-shrug":{squeeze_cue:"Sube los hombros directo hacia las orejas y haz una pausa, sintiendo cómo se aprieta el trapecio superior.",posture_tips:["Toma la barra de un rack a la altura de los muslos con agarre prono al ancho de hombros.","Mantén los brazos rectos, el pecho arriba y la barbilla neutra, sin mirar hacia arriba.","Sube los hombros directo hacia las orejas, sostén 1-2 segundos y baja en 2 segundos hasta estirar por completo.","No gires los hombros en círculos; el movimiento es recto hacia arriba y hacia abajo.","Saca la barra del rack desde la mitad del muslo en lugar de levantarla del piso."]},"dumbbell-shrug":{squeeze_cue:"Encoge los hombros como si quisieras tocarte las orejas y aprieta fuerte el trapecio superior arriba.",posture_tips:["Párate con una mancuerna a cada lado y las palmas hacia tu cuerpo.","Mantén los brazos relajados y rectos, el cuello largo y la mirada al frente.","Encoge los hombros lo más alto posible, sostén 1-2 segundos arriba y baja en 2 segundos hasta estirar el trapecio.","No dobles los codos para ayudarte; tus brazos son solo ganchos.","Usa straps si tu agarre falla antes que el trapecio, en lugar de soltar las mancuernas."]},"hex-bar-shrug":{squeeze_cue:"Sube los hombros directo hacia las orejas y aprieta el trapecio superior como si cargaras un yugo pesado.",posture_tips:["Métete dentro de la barra hexagonal, toma las asas altas y levántate con ella usando las piernas.","Mantén el torso erguido y los hombros alineados con las asas, sin inclinarte.","Encoge los hombros directo hacia arriba, sostén 1-2 segundos arriba y baja en 2 segundos.","No gires los hombros hacia adelante; piensa en subirlos en vertical hacia las orejas.","Levanta y deja la barra con la espalda neutra, igual que en un peso muerto."]},"smith-machine-shrug":{squeeze_cue:"Sube los hombros hacia las orejas y aprieta fuerte el trapecio superior arriba antes de bajar.",posture_tips:["Coloca los topes de seguridad a mitad del muslo, agarra la barra en prono y desengánchala girando las muñecas.","Mantén el cuerpo cerca de la barra y la espalda recta en todo momento.","Sube los hombros siguiendo el recorrido de la barra, sostén 1-2 segundos arriba y baja en 2 segundos.","No acortes el rango con cargas excesivas; el rango importa más que el peso.","Coloca los topes de seguridad justo debajo de la posición inicial antes de empezar."]},"cable-shrug":{squeeze_cue:"Sube los hombros directo hacia las orejas y aprieta fuerte el trapecio superior mientras la polea te jala hacia abajo.",posture_tips:["Coloca una barra recta en la polea baja, agárrala en prono y párate cerca de la columna de peso.","Mantén los brazos rectos y el torso vertical, sin inclinarte hacia la polea.","Encoge los hombros hacia las orejas contra el cable, sostén 1-2 segundos y baja en 2-3 segundos hasta estirar por completo.","No rebotes abajo; aprovecha la tensión constante del cable en todo el rango.","Apoya bien los pies y párate lo bastante cerca para que el cable no te desequilibre."]}};export{a as default};
